export interface EventPayload<T = unknown> {
  readonly id: string;
  readonly type: string;
  readonly timestamp: number;
  readonly data: T;
}

export type EventHandler<T = unknown> = (event: EventPayload<T>) => Promise<void> | void;

export class EventDispatcher {
  private readonly handlers: Map<string, Set<EventHandler>> = new Map();

  subscribe<T = unknown>(type: string, handler: EventHandler<T>): () => void {
    const set = this.handlers.get(type) ?? new Set();
    set.add(handler as EventHandler);
    this.handlers.set(type, set);
    return () => {
      set.delete(handler as EventHandler);
    };
  }

  async dispatch<T = unknown>(event: EventPayload<T>): Promise<readonly Error[]> {
    const set = this.handlers.get(event.type);
    if (!set || set.size === 0) return [];
    const errors: Error[] = [];
    const promises = Array.from(set).map(async (h) => {
      try {
        await h(event as EventPayload);
      } catch (err) {
        errors.push(err instanceof Error ? err : new Error(String(err)));
      }
    });
    await Promise.allSettled(promises);
    return errors;
  }
}
